UPDATE architecture_import SET image=image||'","view":"細部","note":"内外装の具体化 v2：城の大広間。外装の正面・側面、家具入り平面、室内断面、ブロック候補を寸法付きで追加。設計案でありゲーム画面ではありません。全棟・全階の完成図ではありません。","source":""}' WHERE title='動き出す影鬼ごっこ';
UPDATE idea_references SET content=json_set(content,
'$.brief',json_extract(content,'$.brief')||(SELECT addition FROM architecture_import JOIN ideas ON ideas.title=architecture_import.title WHERE ideas.id=idea_references.idea_id),
'$.images[#]',json((SELECT image FROM architecture_import JOIN ideas ON ideas.title=architecture_import.title WHERE ideas.id=idea_references.idea_id)))
WHERE kind='stage' AND idea_id IN (SELECT id FROM ideas JOIN architecture_import ON ideas.title=architecture_import.title)
AND json_array_length(content,'$.images')<6 AND instr(content,'【内外装の具体化 v2】')=0
AND length(json_extract(content,'$.brief'))+(SELECT length(addition) FROM architecture_import JOIN ideas ON ideas.title=architecture_import.title WHERE ideas.id=idea_references.idea_id)<=3000;
DROP TABLE architecture_import;
